# boundary edge counts between colors
def binfo(g):
    R,C=len(g),len(g[0]); pairs=0; same={0:0,1:0}
    vals=set(x for r in g for x in r)
    tot={v:0 for v in vals}; bnd={v:0 for v in vals}
    for i in range(R):
        for j in range(C):
            for da,db in ((1,0),(0,1)):
                p,q=i+da,j+db
                if p<R and q<C:
                    if g[p][q]==g[i][j]: tot[g[i][j]]+=1
                    else: bnd[g[i][j]]+=1; bnd[g[p][q]]+=1
    return tot,bnd
