# line runs: max horizontal run lengths
def maxrun(g,v):
    best=0
    for r in g:
        c=0
        for x in r:
            c=c+1 if x==v else 0
            best=max(best,c)
    # vertical
    for j in range(len(g[0])):
        c=0
        for i in range(len(g)):
            c=c+1 if g[i][j]==v else 0
            best=max(best,c)
    return best
for name,g,z,k in [("d1",g1full,5,2),("d2",g2,7,5)]:
